#[derive(Clone, Copy, PartialEq, Eq)]
enum CompositeType {
    Vector,
    Matrix,
    Array,
    ArrayArray,
    Struct,
    StructStruct,
    Coopmat,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum InstType {
    Value,
    Constant,
    SpecConstant,
}

fn two_as_bits() -> u32 {
    2.0f32.to_bits()
}

struct ReplicatedCompositesTest {
    name: String,
    composite_type: CompositeType,
    inst_type: InstType,
    programs: BinaryCollection,
}

impl TestCase for ReplicatedCompositesTest {
    fn name(&self) -> &str {
        &self.name
    }

    /// `ReplicatedCompositesTest::checkSupport`
    fn check_support(&self, context: &Context<'_>) -> Result<(), TestError> {
        check_shader_object_requirements(ComputePipelineConstructionType::Pipeline)?;

        let mut replicated_features = vk::PhysicalDeviceShaderReplicatedCompositesFeaturesEXT::default();
        {
            let mut features2 = vk::PhysicalDeviceFeatures2::builder().push_next(&mut replicated_features);
            unsafe {
                context
                    .get_instance()
                    .get_physical_device_features2(context.get_physical_device(), &mut features2)
            };
        }
        if replicated_features.shader_replicated_composites == vk::FALSE {
            return Err(TestError::NotSupported(
                "shaderReplicatedComposites not supported".to_string(),
            ));
        }

        if self.composite_type == CompositeType::Coopmat {
            let mut coopmat_features = vk::PhysicalDeviceCooperativeMatrixFeaturesKHR::default();
            {
                let mut features2 = vk::PhysicalDeviceFeatures2::builder().push_next(&mut coopmat_features);
                unsafe {
                    context
                        .get_instance()
                        .get_physical_device_features2(context.get_physical_device(), &mut features2)
                };
            }
            if coopmat_features.cooperative_matrix == vk::FALSE {
                return Err(TestError::NotSupported(
                    "VkPhysicalDeviceCooperativeMatrixFeaturesKHR::cooperativeMatrix not supported".to_string(),
                ));
            }

            let properties = unsafe {
                context
                    .get_instance()
                    .get_physical_device_cooperative_matrix_properties_khr(context.get_physical_device())
            }
            .vk_check("vkGetPhysicalDeviceCooperativeMatrixPropertiesKHR")?;
            let found_fp16 = properties
                .iter()
                .any(|p| p.scope == vk::ScopeKHR::SUBGROUP && p.a_type == vk::ComponentTypeKHR::FLOAT16);
            if !found_fp16 {
                return Err(TestError::NotSupported(
                    "cooperativeMatrix float16 not supported".to_string(),
                ));
            }
        }
        Ok(())
    }

    fn programs(&self) -> BinaryCollection {
        self.programs
    }

    fn create_instance<'a>(&'a self, context: &'a Context<'a>) -> Box<dyn TestInstance + 'a> {
        Box::new(ReplicatedCompositesInstance {
            context,
            composite_type: self.composite_type,
            inst_type: self.inst_type,
        })
    }
}

struct ReplicatedCompositesInstance<'a> {
    context: &'a Context<'a>,
    composite_type: CompositeType,
    inst_type: InstType,
}

impl ReplicatedCompositesInstance<'_> {
    /// `MultiQueueRunnerTestInstance(context, COMPUTE_QUEUE)`: the universal queue, plus the compute-only family's when there is one.
    fn queues(&self) -> Vec<(vk::Queue, u32)> {
        let mut queues = vec![(
            self.context.get_universal_queue(),
            self.context.get_universal_queue_family_index(),
        )];
        if let Some((queue, family)) = self.context.get_compute_queue()
            && family != self.context.get_universal_queue_family_index()
        {
            queues.push((queue, family));
        }
        queues
    }

    /// `ReplicatedCompositesTestInstance::queuePass`
    fn queue_pass(&self, queue: vk::Queue, queue_family_index: u32) -> TestOutcome {
        let context = self.context;
        let device = context.get_device();
        let allocator = context.get_default_allocator();

        // Create a buffer and host-visible memory for it
        let buffer_size_bytes: u64 = 256;
        let buffer = BufferWithMemory::new(
            device,
            allocator,
            make_buffer_create_info(buffer_size_bytes, vk::BufferUsageFlags::STORAGE_BUFFER),
            MemoryRequirement::HOST_VISIBLE,
        )?;
        unsafe { std::ptr::write_bytes(buffer.get_allocation().get_host_ptr(), 0, buffer_size_bytes as usize) };
        flush_alloc(device, buffer.get_allocation())?;

        // Create descriptor set
        let descriptor_set_layout = DescriptorSetLayoutBuilder::new()
            .add_single_binding(vk::DescriptorType::STORAGE_BUFFER, vk::ShaderStageFlags::COMPUTE)
            .build(device)?;
        let descriptor_pool = DescriptorPoolBuilder::new()
            .add_type(vk::DescriptorType::STORAGE_BUFFER, 1)
            .build(device, vk::DescriptorPoolCreateFlags::FREE_DESCRIPTOR_SET, 1)?;
        let descriptor_set = make_descriptor_set(device, *descriptor_pool, *descriptor_set_layout)?;

        let descriptor_info = [make_descriptor_buffer_info(buffer.get(), 0, buffer_size_bytes)];
        let write = vk::WriteDescriptorSet::builder()
            .dst_set(*descriptor_set)
            .dst_binding(0)
            .descriptor_type(vk::DescriptorType::STORAGE_BUFFER)
            .buffer_info(&descriptor_info)
            .build();
        unsafe { device.update_descriptor_sets(&[write], &[] as &[vk::CopyDescriptorSet]) };

        // Perform the computation
        let mut pipeline = ComputePipelineWrapper::new(
            device,
            ComputePipelineConstructionType::Pipeline,
            context.get_binary_collection().get("comp")?,
        );
        pipeline.set_descriptor_set_layout(*descriptor_set_layout);

        let (mut coopmat_rows, mut coopmat_cols) = (0u32, 0u32);
        if self.composite_type == CompositeType::Coopmat {
            let properties = unsafe {
                context
                    .get_instance()
                    .get_physical_device_cooperative_matrix_properties_khr(context.get_physical_device())
            }
            .vk_check("vkGetPhysicalDeviceCooperativeMatrixPropertiesKHR")?;

            for p in &properties {
                if p.scope != vk::ScopeKHR::SUBGROUP {
                    continue;
                }

                if p.a_type == vk::ComponentTypeKHR::FLOAT16 && p.m_size * p.k_size > coopmat_rows * coopmat_cols {
                    coopmat_rows = p.m_size;
                    coopmat_cols = p.k_size;
                }
            }
            debug_assert!(coopmat_rows * coopmat_cols > 0);
        }

        let specialization_data = [two_as_bits(), coopmat_rows, coopmat_cols];
        let specialization_maps = vec![
            vk::SpecializationMapEntry {
                constant_id: 0,
                offset: 0,
                size: 4,
            },
            vk::SpecializationMapEntry {
                constant_id: 1,
                offset: 4,
                size: 4,
            },
            vk::SpecializationMapEntry {
                constant_id: 2,
                offset: 8,
                size: 4,
            },
        ];
        pipeline.set_specialization_info(
            specialization_maps,
            specialization_data.iter().flat_map(|word| word.to_ne_bytes()).collect(),
        );
        pipeline.build_pipeline()?;

        let compute_finish_barrier = make_buffer_memory_barrier(
            vk::AccessFlags::SHADER_WRITE,
            vk::AccessFlags::HOST_READ,
            buffer.get(),
            0,
            buffer_size_bytes,
        );

        let command_pool = make_command_pool(device, queue_family_index)?;
        let command_buffer = allocate_command_buffer(device, *command_pool, vk::CommandBufferLevel::PRIMARY)?;
        let cmd = *command_buffer;

        // Start recording commands
        begin_command_buffer(device, cmd)?;

        pipeline.bind(cmd);
        unsafe {
            device.cmd_bind_descriptor_sets(
                cmd,
                vk::PipelineBindPoint::COMPUTE,
                pipeline.get_pipeline_layout(),
                0,
                &[*descriptor_set],
                &[] as &[u32],
            );
            device.cmd_dispatch(cmd, 1, 1, 1);
            device.cmd_pipeline_barrier(
                cmd,
                vk::PipelineStageFlags::COMPUTE_SHADER,
                vk::PipelineStageFlags::HOST,
                vk::DependencyFlags::empty(),
                &[] as &[vk::MemoryBarrier],
                &[compute_finish_barrier],
                &[] as &[vk::ImageMemoryBarrier],
            );
        }

        end_command_buffer(device, cmd)?;

        // Wait for completion
        submit_commands_and_wait(device, queue, cmd)?;

        // Validate the results
        invalidate_alloc(device, buffer.get_allocation())?;

        let out_struct =
            unsafe { std::slice::from_raw_parts(buffer.get_allocation().get_host_ptr(), buffer_size_bytes as usize) };

        let vecelem = if self.inst_type == InstType::SpecConstant {
            2.0f32
        } else {
            1.0f32
        };
        let float_words = |count: usize| -> Vec<u8> {
            std::iter::repeat_n(vecelem.to_bits(), count)
                .flat_map(u32::to_ne_bytes)
                .collect()
        };

        let arr_elem = if self.inst_type == InstType::SpecConstant {
            two_as_bits()
        } else {
            3
        };
        let str_elem = if self.inst_type == InstType::SpecConstant {
            two_as_bits()
        } else {
            6
        };
        let uint_words = |value: u32, count: usize| -> Vec<u8> {
            std::iter::repeat_n(value, count).flat_map(u32::to_ne_bytes).collect()
        };

        let reference = match self.composite_type {
            CompositeType::Vector => float_words(4),
            CompositeType::Matrix => float_words(16),
            CompositeType::Array => uint_words(arr_elem, 3),
            CompositeType::ArrayArray => uint_words(arr_elem, 6),
            CompositeType::Struct => uint_words(str_elem, 3),
            CompositeType::StructStruct => uint_words(str_elem, 6),
            CompositeType::Coopmat => float_words(2),
        };
        debug_assert!(reference.len() as u64 <= buffer_size_bytes);

        if out_struct[..reference.len()] != reference[..] {
            return Ok(TestStatus::fail("Comparison failed"));
        }
        Ok(TestStatus::pass("Compute succeeded"))
    }
}

impl TestInstance for ReplicatedCompositesInstance<'_> {
    /// `MultiQueueRunnerTestInstance::iterate`
    fn iterate(&mut self) -> TestOutcome {
        for (queue, queue_family_index) in self.queues() {
            let status = self.queue_pass(queue, queue_family_index)?;
            if status.code() != TestResult::Pass {
                return Ok(status);
            }
        }
        Ok(TestStatus::pass("Pass"))
    }
}

/// `getComputeOnlyQueueFamily`
fn compute_only_queue_family(context: &Context<'_>) -> Option<u32> {
    let families = unsafe {
        context
            .get_instance()
            .get_physical_device_queue_family_properties(context.get_physical_device())
    };
    families
        .iter()
        .position(|family| {
            family.queue_flags.contains(vk::QueueFlags::COMPUTE)
                && !family.queue_flags.contains(vk::QueueFlags::GRAPHICS)
        })
        .map(|index| index as u32)
}

struct SecondaryCommandBufferComputeOnlyTest {
    programs: BinaryCollection,
}

impl TestCase for SecondaryCommandBufferComputeOnlyTest {
    fn name(&self) -> &str {
        "secondary_compute_only_queue"
    }

    fn check_support(&self, context: &Context<'_>) -> Result<(), TestError> {
        // Find at least one queue family that supports compute queue but does NOT support graphics queue.
        if compute_only_queue_family(context).is_none() {
            return Err(TestError::NotSupported(
                "No queue family found that only supports compute queue.".to_string(),
            ));
        }
        Ok(())
    }

    fn programs(&self) -> BinaryCollection {
        self.programs
    }

    fn create_instance<'a>(&'a self, context: &'a Context<'a>) -> Box<dyn TestInstance + 'a> {
        Box::new(SecondaryCommandBufferComputeOnlyInstance { context })
    }
}

struct SecondaryCommandBufferComputeOnlyInstance<'a> {
    context: &'a Context<'a>,
}

/// A device that only has the compute-only queue family, destroyed with the scope (`createComputeOnlyDevice`).
struct ComputeOnlyDevice {
    device: Device,
    queue_family_index: u32,
}

impl Drop for ComputeOnlyDevice {
    fn drop(&mut self) {
        unsafe {
            let _ = self.device.device_wait_idle();
            self.device.destroy_device(None);
        }
    }
}

impl TestInstance for SecondaryCommandBufferComputeOnlyInstance<'_> {
    /// `SecondaryCommandBufferComputeOnlyTestInstance::iterate`
    fn iterate(&mut self) -> TestOutcome {
        let context = self.context;
        let instance = context.get_instance();
        let physical_device = context.get_physical_device();
        note_construction_type_independent();

        let queue_family_index = compute_only_queue_family(context).ok_or_else(|| {
            TestError::NotSupported("No queue family found that only supports compute queue.".to_string())
        })?;
        let priorities = [1.0f32];
        let queue_infos = [vk::DeviceQueueCreateInfo::builder()
            .queue_family_index(queue_family_index)
            .queue_priorities(&priorities)
            .build()];
        let device_info = vk::DeviceCreateInfo::builder().queue_create_infos(&queue_infos);
        let created =
            unsafe { instance.create_device(physical_device, &device_info, None) }.vk_check("vkCreateDevice")?;
        let compute_device = ComputeOnlyDevice {
            device: created,
            queue_family_index,
        };
        let device = &compute_device.device;
        let allocator =
            SimpleAllocator::new(unsafe { instance.get_physical_device_memory_properties(physical_device) });

        let queue = unsafe { device.get_device_queue(queue_family_index, 0) };

        let buffer_size = 4u64;
        let buffer = BufferWithMemory::new(
            device,
            &allocator,
            make_buffer_create_info(buffer_size, vk::BufferUsageFlags::STORAGE_BUFFER),
            MemoryRequirement::HOST_VISIBLE,
        )?;
        unsafe { std::ptr::write_bytes(buffer.get_allocation().get_host_ptr(), 0, 4) };
        flush_alloc(device, buffer.get_allocation())?;

        let descriptor_set_layout = DescriptorSetLayoutBuilder::new()
            .add_single_binding(vk::DescriptorType::STORAGE_BUFFER, vk::ShaderStageFlags::COMPUTE)
            .build(device)?;
        let descriptor_pool = DescriptorPoolBuilder::new()
            .add_type(vk::DescriptorType::STORAGE_BUFFER, 1)
            .build(device, vk::DescriptorPoolCreateFlags::FREE_DESCRIPTOR_SET, 1)?;
        let descriptor_set = make_descriptor_set(device, *descriptor_pool, *descriptor_set_layout)?;

        // Update descriptor sets.
        let buffer_info = [make_descriptor_buffer_info(buffer.get(), 0, buffer_size)];
        let write = vk::WriteDescriptorSet::builder()
            .dst_set(*descriptor_set)
            .dst_binding(0)
            .descriptor_type(vk::DescriptorType::STORAGE_BUFFER)
            .buffer_info(&buffer_info)
            .build();
        unsafe { device.update_descriptor_sets(&[write], &[] as &[vk::CopyDescriptorSet]) };

        let shader = create_shader_module(device, context.get_binary_collection().get("comp")?)?;
        // Create compute pipeline
        let set_layouts = [*descriptor_set_layout];
        let layout_info = vk::PipelineLayoutCreateInfo::builder().set_layouts(&set_layouts);
        let pipeline_layout = Unique::new(
            device,
            unsafe { device.create_pipeline_layout(&layout_info, None) }.vk_check("vkCreatePipelineLayout")?,
        );
        let stage = vk::PipelineShaderStageCreateInfo::builder()
            .stage(vk::ShaderStageFlags::COMPUTE)
            .module(*shader)
            .name(b"main\0");
        let pipeline_info = vk::ComputePipelineCreateInfo::builder()
            .stage(*stage)
            .layout(*pipeline_layout)
            .base_pipeline_index(0);
        let compute_pipeline = Unique::new(
            device,
            unsafe { device.create_compute_pipelines(vk::PipelineCache::null(), &[pipeline_info], None) }
                .vk_check("vkCreateComputePipelines")?
                .0[0],
        );

        // Create command buffer
        let command_pool = make_command_pool(device, compute_device.queue_family_index)?;
        let cmd_buffer = allocate_command_buffer(device, *command_pool, vk::CommandBufferLevel::PRIMARY)?;
        let cmd_buffer2 = allocate_command_buffer(device, *command_pool, vk::CommandBufferLevel::SECONDARY)?;

        let inheritance_info = vk::CommandBufferInheritanceInfo::builder()
            .render_pass(vk::RenderPass::null())
            .subpass(0)
            .framebuffer(vk::Framebuffer::null())
            .occlusion_query_enable(false);
        let begin_info = vk::CommandBufferBeginInfo::builder()
            .flags(vk::CommandBufferUsageFlags::ONE_TIME_SUBMIT)
            .inheritance_info(&inheritance_info);

        begin_command_buffer(device, *cmd_buffer)?;
        unsafe {
            device
                .begin_command_buffer(*cmd_buffer2, &begin_info)
                .vk_check("vkBeginCommandBuffer")?;
            device.cmd_bind_pipeline(*cmd_buffer2, vk::PipelineBindPoint::COMPUTE, *compute_pipeline);
            device.cmd_bind_descriptor_sets(
                *cmd_buffer2,
                vk::PipelineBindPoint::COMPUTE,
                *pipeline_layout,
                0,
                &[*descriptor_set],
                &[] as &[u32],
            );
            device.cmd_dispatch(*cmd_buffer2, 1, 1, 1);
        }
        end_command_buffer(device, *cmd_buffer2)?;
        let render_buffer_barrier = make_buffer_memory_barrier(
            vk::AccessFlags::SHADER_WRITE,
            vk::AccessFlags::HOST_READ,
            buffer.get(),
            0,
            buffer_size,
        );
        unsafe {
            device.cmd_execute_commands(*cmd_buffer, &[*cmd_buffer2]);
            device.cmd_pipeline_barrier(
                *cmd_buffer,
                vk::PipelineStageFlags::COMPUTE_SHADER,
                vk::PipelineStageFlags::HOST,
                vk::DependencyFlags::empty(),
                &[] as &[vk::MemoryBarrier],
                &[render_buffer_barrier],
                &[] as &[vk::ImageMemoryBarrier],
            );
        }
        end_command_buffer(device, *cmd_buffer)?;
        submit_commands_and_wait(device, queue, *cmd_buffer)?;

        invalidate_alloc(device, buffer.get_allocation())?;

        let result = unsafe { buffer.get_allocation().get_host_ptr().cast::<u32>().read_unaligned() };
        if result != 1 {
            // upstream reports a pass here
            return Ok(TestStatus::pass("value of buffer unexpected"));
        }

        Ok(TestStatus::pass("passed"))
    }
}

/// The `replicated_composites_*` cases and `secondary_compute_only_queue` of the `basic` group
pub fn create_replicated_composites_cases() -> Vec<Box<dyn TestCase>> {
    let mut cases: Vec<Box<dyn TestCase>> = Vec::new();

    cases.push(Box::new(SecondaryCommandBufferComputeOnlyTest {
        programs: SECONDARY_COMPUTE_ONLY_QUEUE.programs,
    }));

    let inst_names = [
        (InstType::Value, "value"),
        (InstType::Constant, "constant"),
        (InstType::SpecConstant, "specconstant"),
    ];
    let composites = [
        (CompositeType::Vector, "vector"),
        (CompositeType::Matrix, "matrix"),
        (CompositeType::Array, "array"),
        (CompositeType::ArrayArray, "array_array"),
        (CompositeType::Struct, "struct"),
        (CompositeType::StructStruct, "struct_struct"),
        (CompositeType::Coopmat, "coopmat"),
    ];
    for (inst_type, inst_name) in inst_names {
        for (composite_type, composite_name) in composites {
            let programs = match (composite_name, inst_name) {
                ("vector", "value") => RC_VECTOR_VALUE.programs,
                ("vector", "constant") => RC_VECTOR_CONSTANT.programs,
                ("vector", "specconstant") => RC_VECTOR_SPECCONSTANT.programs,
                ("matrix", "value") => RC_MATRIX_VALUE.programs,
                ("matrix", "constant") => RC_MATRIX_CONSTANT.programs,
                ("matrix", "specconstant") => RC_MATRIX_SPECCONSTANT.programs,
                ("array", "value") => RC_ARRAY_VALUE.programs,
                ("array", "constant") => RC_ARRAY_CONSTANT.programs,
                ("array", "specconstant") => RC_ARRAY_SPECCONSTANT.programs,
                ("array_array", "value") => RC_ARRAY_ARRAY_VALUE.programs,
                ("array_array", "constant") => RC_ARRAY_ARRAY_CONSTANT.programs,
                ("array_array", "specconstant") => RC_ARRAY_ARRAY_SPECCONSTANT.programs,
                ("struct", "value") => RC_STRUCT_VALUE.programs,
                ("struct", "constant") => RC_STRUCT_CONSTANT.programs,
                ("struct", "specconstant") => RC_STRUCT_SPECCONSTANT.programs,
                ("struct_struct", "value") => RC_STRUCT_STRUCT_VALUE.programs,
                ("struct_struct", "constant") => RC_STRUCT_STRUCT_CONSTANT.programs,
                ("struct_struct", "specconstant") => RC_STRUCT_STRUCT_SPECCONSTANT.programs,
                ("coopmat", "value") => RC_COOPMAT_VALUE.programs,
                ("coopmat", "constant") => RC_COOPMAT_CONSTANT.programs,
                _ => RC_COOPMAT_SPECCONSTANT.programs,
            };
            cases.push(Box::new(ReplicatedCompositesTest {
                name: format!("replicated_composites_{composite_name}_{inst_name}"),
                composite_type,
                inst_type,
                programs,
            }));
        }
    }

    cases
}
